def main():
    src = json.load(open(SRC, encoding="utf-8"))
    assert len(src) == 107, f"esperaba 107, hay {len(src)}"
    out = []
    for item in src:
        q, opts = T[item["id"]]
        assert len(opts) == len(item["options"]), f"opciones id {item['id']}"
        out.append({
            "id": item["id"], "category": item["category"], "question": q,
            "options": opts, "correct": item["correct"], "multiSelect": item["multiSelect"],
        })
    os.makedirs(os.path.dirname(OUT), exist_ok=True)
    with open(OUT, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
    print(f"OK: {len(out)} preguntas traducidas → {OUT}")

if __name__ == "__main__":
    main()